    "batchImport.guide.currentSupport": "当前入口已支持“账单记录模板”和“基金记录模板”的 CSV、XLSX、XLS 上传、弹窗预览确认和导入；信用卡账单已合并到“账单记录模板”，按信用卡账户、入账日期和还款转账规则预览校验。",
    "batchImport.guide.fundImportNotes": "填写说明\t以下可以删除也可以放置不管，系统导入时会忽略。\n交易日期\t必填，资金账户侧变动时间。\n净值日期\t选填，正常与申请日期相同；若申请日期晚于 15:00，则净值日期=交易日期+1。留空时由系统按确认日规则获取。\n入账日期\t选填，购买份额加入持仓的日期，一般 T+1 或 T+2。留空时由系统按到账日规则获取。\n基金动作\t必填，只有 4 类：买入、赎回、现金分红、红利再投。\n基金代码\t必填\n金额\t必填，红利再投时可不填\n手续费率\t选填，默认百分比，比如填1，则是按百分之一收取手续费\n手续费\t选填，按金额参与扣减。\n净值\t选填，填写则按填写净值计算份额；不填则入库后由系统获取净值并计算份额。\n份额\t选填，填写则按填写份额入库；不填则计算后入库。\n标签\t选填，多个标签用逗号、顿号或分号分隔；标签不存在时会自动创建到标签库。\n备注\t选填",
    "batchImport.guide.normalBill": "账单记录按中文字段导入：当前模板用 `流出/流入` 表达账户侧方向，不再额外放 `金额` 列。旧文件或自定义文件如果只有 `金额` 一列，系统仍会按金额正负号、收支大类和还款/退款关键词兜底判断。`分类` 对应分类，`标签` 对应标签关联，`备注` 对应备注。转账时，`账户` 可按当前账户视角填写，`对向账户` 填另一侧账户；信用卡还款也按转账处理，可把信用卡放在账户列并把还款额填入流入。旧文件如果仍使用“类型/原始类型”或旧信用卡模板的 `cardAccount/type/merchant` 列，系统也继续兼容识别。",
    "batchImport.guide.wechatBill": "微信模板按微信支付账单导出字段组织：会从表头说明区读取微信昵称/用户/所有人；`支付方式` 留空、写 `/` 或零钱时，会优先匹配该所有人的微信零钱账户；`当前状态` 为已全额退款或已退还时会跳过。支付宝账单同样会读取表头姓名，并优先匹配该所有人的支付宝余额、余额宝或花呗账户。",
    "batchImport.guide.jdBill": "京东模板按京东交易流水导出字段组织：`交易说明` 会写入主备注；`收/支` 为不计收支且提示还款成功时，按 `收/付款方式` 向 `商户名称` 转账；当 `收/付款方式` 与 `商户名称` 都能匹配系统账户，且交易说明含转入/转出时，按内部转账处理：转入为 `收/付款方式` 转入 `商户名称`，转出为 `商户名称` 转出到 `收/付款方式`；退款成功按支出退款处理，金额列保留负数，并优先沿用相同备注原支出的分类（会忽略开头的 `退款-`）；金额里的 `(已全额退款)` 会先清理再识别；微信支付和云闪付不会自动匹配资金账户，需要在预览中手动选择。",
