    "batchImport.template.normal.field.account": "对应主账户。支出/收入写发生账户；转账可写当前视角账户。信用卡消费、退款、还款可统一写信用卡账户，再用流入/流出表达方向。",
    "batchImport.template.normal.field.counterAccount": "对应转账另一侧账户。信用卡还款若账户列是信用卡，这里写付款账户；若账户列是付款账户，这里写信用卡账户。",
