    "productIntro.title": "MoneyMoneyHome",
    "productIntro.mantra": "哦嘛呢嘛呢吽",
    "productIntro.lead": "一套本地部署、覆盖现金、基金、股票、房产和保险的家庭财务工作台。",
    "productIntro.paragraph1": "一套面向家庭和个人的本地优先智能财务管理系统，以本地数据安全存储为基础，把日常记账、账户资产、信用卡账单、基金定投、股票持仓、房产与固定资产、保险保单、房贷还款、往来款和邮箱账单识别串成一套可以长期维护的家庭财务工作台。",
    "productIntro.paragraph2": "它不只是记录每一笔账、显示当前的资产状态，而是尽量把复杂流程自动化：力求在可能的范围内减少用户输入，将记账这个繁琐的工作尽量简单化，变成一个可持续的日常操作。",
    "productIntro.paragraph3": "系统支持 Web、移动端、开放 API 等多种入口，让同一套家庭财务数据在不同界面之间保持统一、准确、可追溯。",
    "productIntro.highlight.dailyBookkeeping": "日常记账",
    "productIntro.highlight.accounts": "账户资产",
    "productIntro.highlight.creditCards": "信用卡账单",
    "productIntro.highlight.funds": "基金定投",
