    "viewImport.source": "来源",
    "viewImport.units": "份额",
    "viewImport.notesIntroNormal": "第 1 行是表头，导入时按表头名称识别；请不要修改表头文字，数据从第 2 行开始填写。",
    "viewImport.notesRecognitionNormal": "系统只识别有明确表头和收支方向的字段；不能确定含义时会在预览里报错或警告，不会把字段强行改作其他用途。",
    "viewImport.sheetGuideTitleCombined": "本页字段说明（导入时从本行开始以下的信息会被忽略，可以保留，无需删除。）",
    "viewImport.notesDate": "写交易日期，推荐 YYYY-MM-DD；也兼容常见 Excel 日期。",
    "viewImport.notesPostedAt": "支出记录可填实际入账日期；留空时用日期替换，无法识别时预览警告并按空值处理。",
    "viewImport.notesActivityType": "信用卡还款也填写“转账”，系统按账户方向识别，不需要在分类里写信用卡还款。",
    "viewImport.notesAmount": "统一填正数；方向优先看“流出/流入”，未填写时再按收支大类推断。",
    "viewImport.notesOutflow": "账户侧资金减少时填写，例如消费、转出、取现。",
    "viewImport.notesInflow": "账户侧资金增加时填写，例如收入、信用卡还款、退款、退货、冲正。",
    "viewImport.notesAccount": "支出/收入写发生账户；转账可写当前视角账户；信用卡账单页导入时可统一写当前信用卡账户。",
    "viewImport.notesCounterAccount": "仅转账时填写另一侧账户。信用卡还款若账户列是信用卡，这里写付款账户；若账户列是付款账户，这里写信用卡账户。非转账记录填写后只会预览警告并忽略。",
    "viewImport.notesCategory": "填写账簿中已有分类名称，系统会按现有分类/学习规则对齐。",
    "viewImport.notesCounterparty": "填写商户、银行、支付机构等明确机构名。",
    "viewImport.notesTags": "多个标签用逗号、顿号或分号分隔；标签不存在时会自动创建到标签库。",
    "viewImport.notesRemark": "自由文本备注。",
    "viewImport.notesIntroFund": "第 1 行是表头，导入时按表头名称识别；请不要修改表头文字，数据从第 2 行开始填写。",
    "viewImport.notesRecognitionFund": "系统只识别有明确表头和业务方向的字段；不能确定含义时会在预览里报错或警告，不会强行改作其他字段。",
    "viewImport.notesFundSubtype": "不同语言模板显示对应本地化名称，导入后映射为系统内部动作。",
    "viewImport.notesCashAccount": "必填，红利再投除外。买入、定投、赎回、现金分红等有现金出入的动作为必填；红利再投无现金出入，可留空。留空时由基金导入规则校验。",
    "viewImport.notesFundAccount": "基金账户，当前模板默认填入本视图账户。",
    "viewImport.notesFundCode": "基金代码是基金记录识别主键；基金名称仅作可选显示信息，不用于匹配。",
    "viewImport.notesFundAmount": "填正数，方向由基金动作决定。",
    "viewImport.notesFundFeeRate": "按费率计算手续费，可填 1.5 或 1.5%，两者都按 1.5% 处理。",
    "viewImport.notesFundFee": "按金额填写实际手续费；不带 % 的数值一律按金额处理。",
    "viewImport.notesFundNav": "成交净值；买入、赎回时用于预估份额，留空时按净值 1 处理。",
    "viewImport.notesFundUnits": "确认份额；会进入基金预览校验，与持仓份额核对。",
    "viewImport.notesFundConfirmDate": "确认/净值日期，推荐 YYYY-MM-DD；留空时按交易日期推算。",
    "viewImport.notesFundArrivalDate": "现金入账日期，推荐 YYYY-MM-DD；留空时按确认日期处理。",
    "viewImport.notesIntroStock": "模板默认按当前股票账户导入；如不在股票账户视图导入，请填写股票账户列。股票代码是识别主键，导入时可以创建尚未持仓的股票证券档案。",
    "viewImport.notesRecognitionStock": "系统按表头识别股票交易字段。买入、卖出、分红、送股、拆股、并股和费用/税费调整会映射为系统股票交易动作。",
    "viewImport.notesStockSettleDate": "填写交割日期，推荐 YYYY-MM-DD；留空时按交易日期处理。",
    "viewImport.notesStockAccount": "必填；系统按名称、ID、别名或账户显示名识别股票账户。",
    "viewImport.notesStockAction": "不同语言模板显示对应本地化名称，导入后映射为系统内部动作。",
    "viewImport.notesStockMarket": "A 股填写沪市/深市/北交所代码，或填 CN 让系统按证券代码推断；港股填 HK，美股填 US。",
    "viewImport.notesStockCode": "上市证券交易行必填证券代码；银证转账行可留空。",
    "viewImport.notesStockQuantity": "买入、卖出、送股、拆股、并股等数量动作需填写；现金分红和费用调整可留空。",
    "viewImport.notesStockPrice": "价格、成交金额、净金额三者填任一项即可，系统可推算其它。填价格 → 成交金额 = 数量 × 价格；也可留空，让系统按交易日收盘价补全价格。",
    "viewImport.notesStockAmount": "价格、成交金额、净金额三者填任一项即可，系统可推算其它。买入/卖出行可直接填成交金额，也可只填价格或净金额让系统推算；分红、费用调整、银证转账等现金行需填成交金额或净金额。银证转账正数表示银行转入证券资金账户，负数表示转回银行。",
    "viewImport.notesStockNetAmount": "价格、成交金额、净金额三者填任一项即可，系统可推算其它。净金额为实际到账/扣款额；填了净金额就可不必填价格。",
    "viewImport.notesStockBankAccount": "只有银证转账行必须填写银行侧账户（所有人、机构、账户名称）；普通证券交易可留空。",
    "viewImport.notesStockFees": "总费用为费用合计，会覆盖下方所有单项费用：填了总费用就按该值计算，不再叠加佣金、印花税等拆分明细。不填总费用时，可拆分填写各单项费用并自动相加；所有费用字段都空时系统按账户费率规则估算。",
    "viewImport.notesStockFeeComponent": "未填写总费用时作为费用拆分；所有费用字段都空时系统按账户费率规则估算。",
