    "batchImport.required": "Required",
    "batchImport.optional": "Optional",
    "batchImport.guideTitle": "Import Guide",
    "batchImport.guide.currentSupport": "This entry now supports CSV, XLSX, and XLS upload plus preview confirmation and import for both the regular bill template and the fund template. Credit card statement records have been merged into the regular bill template, with preview validation for credit card accounts, posting dates, and repayment transfers.",
    "batchImport.guide.fundImportNotes": "Instructions\tYou can delete this section or leave it as-is; the system ignores it during import.\nTrade Date\tRequired. The cash-side change time.\nNAV Date\tOptional. Normally the same as the application date; if the application is after 15:00, NAV date=trade date+1. Leave blank for the system to derive from the confirm-day rule.\nPosting Date\tOptional. The date purchased units enter the position, usually T+1 or T+2. Leave blank for the system to derive from the arrival-day rule.\nFund Action\tRequired. Only four actions: Buy, Redeem, Cash Dividend, Dividend Reinvest.\nFund Code\tRequired.\nAmount\tRequired; may be blank for Dividend Reinvest.\nFee Rate\tOptional. Treated as a percent by default; entering 1 means a 1% fee.\nFee\tOptional. Used as the fee amount deducted from the amount.\nNAV\tOptional. If filled, units are calculated from this NAV; if blank, the system fetches NAV and calculates units after import.\nUnits\tOptional. If filled, units are stored as entered; if blank, units are calculated.\nTags\tOptional. Separate multiple tags with commas or semicolons; tags that do not exist are created in the tag library automatically.\nRemark\tOptional.",
    "batchImport.guide.normalBill": "Bill records are imported by the Chinese contract headers. The current template uses `流出/流入` for account-side direction and no longer adds a separate `金额` column. Older or custom files with only `金额` are still recognized from amount sign, major type, and repayment/refund keywords. `分类` maps to category, `标签` maps to tag relations, and `备注` maps to note. For transfers, `账户` may be the current-side account and `对向账户` is the other side; credit-card repayments are also transfers and may put the credit card in `账户` with the repayment amount in `流入`. Older files using `类型/原始类型` or legacy credit-card columns such as `cardAccount/type/merchant` are still recognized.",
    "batchImport.guide.wechatBill": "The WeChat template follows the WeChat Pay export columns. It reads WeChat nickname/user/owner hints from the header notes; blank, `/`, or 零钱 payment methods prefer that owner's WeChat balance account, and rows marked `已全额退款` or `已退还` are skipped. Alipay bills also read the header name and prefer that owner's Alipay balance, Yu'e Bao, or Huabei account.",
    "batchImport.guide.jdBill": "The JD template follows JD transaction export columns. `交易说明` becomes the main note; non-counted rows that indicate successful repayment are treated as transfers from `收/付款方式` to `商户名称`. When both `收/付款方式` and `商户名称` can match system accounts and the description says transfer-in/out, the row is treated as an internal transfer: transfer-in moves from `收/付款方式` to `商户名称`, and transfer-out moves from `商户名称` to `收/付款方式`. Successful refunds are treated as expense refunds, keep the amount cell negative, and prefer the category from the original expense with the same note, ignoring a leading `退款-`; `(已全额退款)` in the amount is stripped before parsing. WeChat Pay and UnionPay QuickPass are left for manual account selection in preview.",
