    "productIntro.title": "MoneyMoneyHome",
    "productIntro.mantra": "Oh, Many Money Home",
    "productIntro.lead": "A local-first household finance workspace for cash, funds, stocks, property, and insurance.",
    "productIntro.paragraph1": "A local-first intelligent finance system for households and individuals. Built on secure local data storage, it connects daily bookkeeping, account assets, credit card bills, fund investment plans, stock holdings, properties and fixed assets, insurance policies, mortgage repayment, settlements, and email bill recognition into one durable household finance workspace.",
    "productIntro.paragraph2": "It is not just for recording every transaction and showing the current asset state. It aims to automate complex flows wherever practical, reduce user input as much as possible, and make the tedious work of bookkeeping simple enough to become a sustainable daily habit.",
    "productIntro.paragraph3": "The same financial data can be accessed through the Web workspace, mobile apps, scheduled tasks, AI workflows, and open APIs, keeping every interface consistent, accurate, and traceable.",
    "productIntro.highlight.dailyBookkeeping": "Daily Books",
    "productIntro.highlight.accounts": "Account Assets",
    "productIntro.highlight.creditCards": "Card Bills",
