    "viewImport.units": "Units",
    "viewImport.notesIntroNormal": "Row 1 is the header row and import recognizes fields by header name; please do not edit the header text and start entering data from row 2.",
    "viewImport.notesRecognitionNormal": "The system only recognizes fields with clear headers and income/expense direction; when a field's meaning cannot be determined, the preview shows an error or warning instead of forcing the field to another use.",
    "viewImport.sheetGuideTitleCombined": "Sheet field guide (information below this row is ignored on import; you may keep it, no need to delete.)",
    "viewImport.notesDate": "Enter the transaction date, preferably YYYY-MM-DD; common Excel date formats are also accepted.",
    "viewImport.notesPostedAt": "Expense records may include the actual posting date; if left empty, the transaction date is used. If it cannot be recognized, the preview warns and treats it as empty.",
    "viewImport.notesActivityType": "Credit card repayment is also entered as Transfer; the system infers direction from the accounts, so you do not need to write credit card repayment in the category.",
    "viewImport.notesAmount": "Enter positive numbers only; direction is taken from the Outflow/Inflow columns first, then inferred from the activity type when they are empty.",
    "viewImport.notesOutflow": "Fill in when funds decrease on the account side, e.g. spending, transfers out, cash withdrawals.",
    "viewImport.notesInflow": "Fill in when funds increase on the account side, e.g. income, credit card repayment, refunds, returns, reversals.",
    "viewImport.notesAccount": "Expense/income records use the account where they occurred; transfers may use the current view account; when importing on a credit card bill page, you may uniformly use the current credit card account.",
    "viewImport.notesCounterAccount": "Only fill in the other-side account for transfers. For credit card repayment, if the account column holds the credit card, enter the payment account here; if it holds the payment account, enter the credit card account here. On non-transfer records this only triggers a preview warning and is ignored.",
    "viewImport.notesCategory": "Enter an existing category name in the book; the system aligns it using the existing category/learning rules.",
    "viewImport.notesCounterparty": "Enter a clear institution name such as a merchant, bank, or payment provider.",
    "viewImport.notesTags": "Separate multiple tags with commas or semicolons; tags that do not exist are created in the tag library automatically.",
    "viewImport.notesRemark": "Free-text remark.",
    "viewImport.notesIntroFund": "Row 1 is the header row and import recognizes fields by header name; please do not edit the header text and start entering data from row 2.",
    "viewImport.notesRecognitionFund": "The system only recognizes fields with clear headers and business direction; when a field's meaning cannot be determined, the preview shows an error or warning rather than forcing the field to another use.",
    "viewImport.notesFundSubtype": "Each language template shows localized options and import maps them to internal actions.",
    "viewImport.notesCashAccount": "Required, except dividend reinvest. Actions with cash flow such as buy, recurring buy, redeem, and cash dividend require it; dividend reinvest has no cash flow and may be left empty. When left empty, the fund import rules validate it.",
    "viewImport.notesFundAccount": "The fund account; this template defaults to the current view account.",
    "viewImport.notesFundCode": "The fund code is the identity key for fund records; fund name is optional display information and is not used for matching.",
    "viewImport.notesFundAmount": "Enter a positive number; the direction is determined by the fund action.",
    "viewImport.notesFundFeeRate": "Fee calculated by rate: enter 1.5 or 1.5%, both are treated as 1.5%.",
    "viewImport.notesFundFee": "Enter the actual fee amount; numeric values without % are always treated as amounts.",
    "viewImport.notesFundNav": "Execution NAV; used to estimate units on buy/redeem, and treated as 1 when blank.",
    "viewImport.notesFundUnits": "Confirmed units; validated in the fund preview against the holding units.",
    "viewImport.notesFundConfirmDate": "Confirmation/NAV date, preferably YYYY-MM-DD; inferred from the trade date when blank.",
    "viewImport.notesFundArrivalDate": "Cash posting date, preferably YYYY-MM-DD; falls back to the confirmation date when blank.",
    "viewImport.notesIntroStock": "The template defaults to the current stock account. If importing outside a stock-account view, fill the Stock Account column. Stock code is the identity key, and import can create securities that do not have an existing holding yet.",
    "viewImport.notesRecognitionStock": "The system recognizes stock transaction fields by header. Buy, sell, dividend, bonus share, split, merge, fee adjustment, and tax adjustment map to system stock actions.",
    "viewImport.notesStockSettleDate": "Enter the settlement date, preferably YYYY-MM-DD; if blank, the trade date is used.",
    "viewImport.notesStockAccount": "Required; the system identifies the stock account by name, ID, alias, or display label.",
    "viewImport.notesStockAction": "Each language template shows localized options and import maps them to internal actions.",
    "viewImport.notesStockMarket": "For A-shares enter the Shanghai/Shenzhen/Beijing code, or enter CN to infer the exchange from the security code; use HK for Hong Kong and US for US stocks.",
    "viewImport.notesStockCode": "Security transaction rows require a security code; bank-securities transfer rows may leave it blank.",
    "viewImport.notesStockQuantity": "Quantity-based actions such as buy, sell, bonus shares, split, and merge require quantity; cash dividends and fee adjustments may leave it blank.",
    "viewImport.notesStockPrice": "Fill any one of price, gross amount, or net amount; the system can derive the rest. If you fill price, gross amount = quantity × price. You may also leave it blank for the system to fill price from the trade-date close price.",
    "viewImport.notesStockAmount": "Fill any one of price, gross amount, or net amount; the system can derive the rest. Buy/sell rows may enter gross amount directly, or only price/net amount and let the system derive. Cash rows such as dividend, fee adjustment, and bank-securities transfer need gross or net amount. Positive bank-securities transfer means bank to brokerage cash account; negative means back to bank.",
    "viewImport.notesStockNetAmount": "Fill any one of price, gross amount or net amount; the system can derive the rest. Net amount is the actual credited/debited amount; if filled, price may be left blank.",
    "viewImport.notesStockBankAccount": "Only bank-securities transfer rows must enter the bank-side account (owner, institution, account name); ordinary security trades may leave it blank.",
    "viewImport.notesStockFees": "Total fee is the fee total and overrides every individual fee below: when filled, import uses it as the total and does not add split components such as commission or stamp duty. If you leave total fee blank, you can fill the split fee components and they are summed. When all fee fields are blank, the system estimates fees from account rules.",
    "viewImport.notesStockFeeComponent": "Fee component used only when total fee is blank. When all fee fields are blank, the system estimates fees from account rules.",
