    "batchImport.required": "必須",
    "batchImport.optional": "任意",
    "batchImport.guideTitle": "インポート案内",
    "batchImport.guide.currentSupport": "この画面では現在、「帳票記録テンプレート」と「基金記録テンプレート」の CSV、XLSX、XLS のアップロード、プレビュー確認、取り込みに対応しています。クレジットカード明細記録は「帳票記録テンプレート」に統合され、カード口座、入帳日、返済振替ルールでプレビュー検証します。",
    "batchImport.guide.fundImportNotes": "記入説明\tこの説明欄は削除しても、そのまま残してもかまいません。インポート時に無視されます。\n取引日\t必須。資金口座側の変動日時です。\n基準価額日\t任意。通常は申込日と同じです。申込日が 15:00 より後の場合は基準価額日=取引日+1。空欄なら確認日ルールから導出します。\n入帳日\t任意。購入口数が保有に加わる日で、通常 T+1 または T+2。空欄なら到着日ルールから導出します。\n基金アクション\t必須。購入、解約、現金分配、分配金再投資の 4 種類のみです。\n基金コード\t必須。\n金額\t必須。分配金再投資では空欄可。\n手数料率\t任意。既定で百分率として扱います。1 と入力すると 1% の手数料です。\n手数料\t任意。金額として控除に使用します。\n基準価額\t任意。入力すればその基準価額で口数を計算します。空欄ならインポート後にシステムが取得して計算します。\n口数\t任意。入力すればその口数を保存し、空欄なら計算して保存します。\nタグ\t任意。複数のタグはカンマ・読点・セミコロンで区切ります。存在しないタグはタグライブラリに自動作成されます。\n備考\t任意。",
    "batchImport.guide.normalBill": "帳票記録は中国語の契約ヘッダーで取り込みます。現在のテンプレートは `流出/流入` で口座側の方向を表し、別の `金额` 列は追加しません。旧ファイルやカスタムファイルで `金额` だけの場合も、金額の符号、記録種別、返済/返金キーワードで引き続き認識します。`分类` はカテゴリ、`标签` はタグ関連、`备注` は備考に対応します。振替では `账户` を現在側の口座、`对向账户` をもう一方の口座として入力できます。カード返済も振替で、カードを `账户` に置き返済額を `流入` に入力できます。旧ファイルの `类型/原始类型` や旧カード明細テンプレートの `cardAccount/type/merchant` 列も引き続き認識します。",
    "batchImport.guide.wechatBill": "WeChat Pay の明細エクスポート用テンプレートです。表頭のニックネーム/ユーザー/所有者情報を読み取り、`支付方式` が空欄、`/`、または零钱の場合はその所有者の WeChat 残高口座を優先します。`已全额退款` と `已退还` の行は取り込み時に除外します。Alipay 明細も表頭の氏名を読み取り、その所有者の Alipay 残高、余额宝、花呗口座を優先します。",
    "batchImport.guide.jdBill": "JD テンプレートは JD 取引流水のエクスポート項目に合わせています。`交易说明` は主備考として保存します。`收/支` が不計収支で返済成功を示す行は、`收/付款方式` から `商户名称` への振替として扱います。`收/付款方式` と `商户名称` の両方がシステム内口座に一致し、説明に転入/転出がある場合は内部振替として扱います。転入は `收/付款方式` から `商户名称`、転出は `商户名称` から `收/付款方式` です。返金成功は支出の返金として扱い、金額列は負数を保持し、先頭の `退款-` を無視して同じ備考の元支出カテゴリを優先します。金額内の `(已全额退款)` は解析前に除去します。WeChat Pay と UnionPay QuickPass はプレビューで資金口座を手動選択します。",
