    "batchImport.template.normal.field.majorType": "記録の大類を `type` に書き込みます。支出、収入、振替、投資を使用します。クレジットカード返済は振替として入力し、システムが口座方向から返済として識別します。",
    "batchImport.template.normal.field.amount": "`amount` に記録金額を書き込みます。テンプレートでは正数と `outflow` / `inflow` の利用を推奨しますが、金額列だけのファイルも金額の符号、記録種別、返済/返金キーワードから推定します。",
