    "productIntro.title": "MoneyMoneyHome",
    "productIntro.mantra": "オム・マニ・マネー・ホーム",
    "productIntro.lead": "現金、投資信託、株式、不動産、保険まで扱うローカルファーストの家庭財務ワークスペース。",
    "productIntro.paragraph1": "家庭と個人のためのローカルファーストなスマート財務管理システムです。安全なローカルデータ保存を基盤に、日々の記帳、口座資産、クレジットカード明細、投資信託の積立、株式保有、不動産と固定資産、保険契約、住宅ローン返済、立替・貸借、メール明細の認識を、長く使える家庭向け財務ワークスペースにつなぎます。",
    "productIntro.paragraph2": "すべての取引を記録し、現在の資産状態を表示するだけではありません。可能な範囲で複雑な流れを自動化し、ユーザー入力をできるだけ減らして、手間のかかる記帳を日々続けられるシンプルな操作にすることを目指します。",
    "productIntro.paragraph3": "Web、モバイルアプリ、予定タスク、AI ワークフロー、オープン API など複数の入口から同じ財務データに接続し、表示と計算を一貫して正確に保ちます。",
