    "liabilitiesGuide.emptyHint": "借入・貸付・代払い・未精算の取引先を先に追加してください。追加すると、ここに「新規往来金」ボタンが表示されます。",
    "liabilitiesGuide.newDebtTransaction": "新規往来金",
    "liabilitiesGuide.guideTitle": "往来金作成の説明",
    "liabilitiesGuide.selectedHint": "現在の選択：{name}。右上の「新規往来金」をクリックすると、ダイアログの「取引先」にデフォルトで選択されます。ダイアログ内で切り替えたり、直接追加したりすることもできます。",
    "liabilitiesGuide.noSelectionHint": "まず左側で取引先を追加してください。取引先がない場合、無所属の往来口座が作成されないよう「新規往来金」ボタンは表示されません。",
    "liabilitiesGuide.step1Title": "1. 操作タイプを選択",
    "liabilitiesGuide.step1Text": "借入は相手からお金を受け取ること、貸付は相手にお金を渡すことです。返済と回収は既存の残高を減らします。",
    "liabilitiesGuide.step2Title": "2. 資金口座を選択",
    "liabilitiesGuide.step2Text": "資金口座は現金・デビットカード・電子ウォレット・クレジットカード側で、実際のお金の流出入元を記録します。",
    "liabilitiesGuide.step3Title": "3. 取引先を選択",
    "liabilitiesGuide.step3Text": "通常の往来は取引先の選択が必須です。ない場合は左のリストから追加するか、ダイアログの取引先ドロップダウンから直接追加できます。",
    "liabilitiesGuide.step4Title": "4. 往来口座を確認",
    "liabilitiesGuide.step4Text": "個人/組織は通常、その取引先の同じ往来口座を再利用します。口座を選ばない場合、保存時に「○○の往来金」が自動的に再利用または作成されます。",
    "liabilitiesGuide.step5Title": "5. 金額と備考を入力",
    "liabilitiesGuide.step5Text": "元金は往来残高を形成または減らします。利息は返済・回収時のみ必要です。備考は理由の説明用で、例として一時的な資金繰りや食事代の立替などがあります。",
    "liabilitiesGuide.suggestedOrderTitle": "推奨の順序",
