    "debtShell.rateAdjust.hint": "金利調整は発効日以降の返済表とその後の自動返済に影響します。先頭行にはローン実行日とその日の適用金利を表示します。割引は適用金利を LPR（初期は基準金利）と比較して自動算出されます。「再計算」を押すとこの期から返済計画表を再計算します：明細はその場で修正され、返済記録は削除されません。",
    "debtShell.rateAdjust.simpleHint": "消費者ローンの金利調整では発効日と年利率のみを管理します。先頭行にはローン日付と開始金利（0 も可）を表示します。保存後は発効日以降の返済表とその後の自動返済に反映され、実行済みの返済は自動では書き換えません。",
