    "firstUseGuide.step.ledger.action": "台帳設定",
    "firstUseGuide.step.ledger.intro": "「{name}」という台帳を管理していることを先に確認してください。以降のメンバー、口座、初期残高、取引、バックアップ、招待コードはすべてこの台帳に紐づきます。",
    "firstUseGuide.step.ledger.why0": "台帳はデータの分離境界です。異なる家庭、個人の帳簿、テスト用の帳簿を混在させないでください。",
    "firstUseGuide.step.ledger.why1": "台帳の切り替え、データのバックアップ、復元、招待コードによる帳簿作成はすべて台帳の識別情報に依存します。",
