    "firstUseGuide.step.ledger.action1": "正式な台帳の場合は、「デフォルト」「テスト」のような仮の名称を避けてください。",
    "firstUseGuide.step.ledger.action2": "複数人で使う場合は、先に台帳を確定してから、ユーザーと家族メンバーを追加してください。",
    "firstUseGuide.step.ledger.done0": "現在の台帳が表示されています：{name}。",
    "firstUseGuide.step.ledger.done1": "以降の初期化データをこの台帳に書き込むことを確認しました。",
    "firstUseGuide.step.ledger.done2": "今後台帳を切り替えるとき、他の台帳と混同しないことが確認できています。",
    "firstUseGuide.step.ledger.tip0": "台帳はログインユーザー名ではありません。",
    "firstUseGuide.step.ledger.tip1": "台帳は家族メンバーの名前でもありません。",
    "firstUseGuide.step.ledger.tip2": "台帳を間違えて作成した場合は先に切り替えてください。初期データの入力を続けないでください。",
    "firstUseGuide.step.family.detail": "デフォルトメンバー：{name}",
    "firstUseGuide.step.family.action": "メンバーを管理",
    "firstUseGuide.step.family.intro": "家族メンバーは口座、保険、資産、支出の帰属先を決めます。現在のデフォルトメンバーは「{name}」です。台帳名のままなら、実際のメンバー名に変更してください。",
    "firstUseGuide.step.family.why0": "銀行カード、クレジットカード、保険、投資口座は誰のものかを把握する必要があります。",
    "firstUseGuide.step.family.why1": "世帯視点では、以降の統計でメンバーごとの収支、資産、負債を確認できます。",
    "firstUseGuide.step.family.why2": "デフォルトメンバーに台帳名を使い続けると、台帳名とユーザー/メンバーが混ざり、以降の選択が不明確になります。",
    "firstUseGuide.step.family.action0": "デフォルトメンバー「{name}」を実際の氏名または安定した略称に変更してください。",
    "firstUseGuide.step.family.action1": "収支が頻繁にある人、口座を保有する人、保険証券を持つ人をメンバーとして追加してください。",
