    "firstUseGuide.step.investment.intro": "投資口座は基金、資産運用、貴金属などの保有を正しい口座に配置します。基金はコードが計算上の識別子であり、名称は表示専用です。",
    "firstUseGuide.step.investment.why0": "投資資産は購入記録だけでなく、保有数量、コスト、基準価額、保有状況が必要です。",
    "firstUseGuide.step.investment.why1": "期首の保有を明確に入力すれば、収益、過去の損益、その後の申込・解約を継続的に計算できます。",
    "firstUseGuide.step.investment.why2": "口座と商品を分けることで、同じ基金を異なるプラットフォームで保有していても区別できます。",
