    "viewImport.notesIntroNormal": "1行目はヘッダー行で、取り込み時はヘッダー名で項目を認識します。ヘッダー文字列は変更せず、データは2行目から入力してください。",
    "viewImport.notesRecognitionNormal": "システムは明確なヘッダーと収支方向を持つフィールドのみを認識します。意味を判断できない場合は、プレビューでエラーまたは警告を表示し、フィールドを別の用途に無理に変更することはありません。",
