    "viewImport.notesPostedAt": "支出記録には実際の入金日を入力できます。空欄の場合は取引日に置き換えます。認識できない場合はプレビューで警告し、空値として扱います。",
    "viewImport.notesActivityType": "クレジットカード返済も「振替」で入力します。システムが口座の方向で認識するため、カテゴリにクレジットカード返済と書く必要はありません。",
    "viewImport.notesAmount": "正の数で統一して入力します。方向は「流出/流入」列を優先し、未入力の場合は収支区分から推測します。",
    "viewImport.notesOutflow": "口座側の資金が減少する場合に入力します。例：消費、振替出金、現金引き出し。",
    "viewImport.notesInflow": "口座側の資金が増加する場合に入力します。例：収入、クレジットカード返済、返金、返品、訂正。",
    "viewImport.notesAccount": "支出/収入は発生した口座を入力します。振替は現在のビュー口座で可。クレジットカード明細ページでの取り込み時は現在のクレジットカード口座で統一できます。",
    "viewImport.notesCounterAccount": "振替時のみ反対側の口座を入力します。クレジットカード返済の場合、口座列がクレジットカードなら支払い口座を、支払い口座ならクレジットカード口座を入力します。振替以外の記録ではプレビュー警告のみで無視されます。",
    "viewImport.notesCategory": "帳簿に既存のカテゴリ名を入力します。システムは既存のカテゴリ/学習ルールに合わせます。",
    "viewImport.notesCounterparty": "加盟店、銀行、決済機関など明確な機関名を入力します。",
    "viewImport.notesTags": "複数のタグはカンマ・読点・セミコロンで区切ります。存在しないタグはタグライブラリに自動作成されます。",
    "viewImport.notesRemark": "自由文の備考。",
    "viewImport.notesIntroFund": "1行目はヘッダー行で、取り込み時はヘッダー名で項目を認識します。ヘッダー文字列は変更せず、データは2行目から入力してください。",
    "viewImport.notesRecognitionFund": "システムは明確なヘッダーと業務方向を持つフィールドのみを認識します。意味を判断できない場合はプレビューでエラーまたは警告を表示し、無理に別のフィールドに変更しません。",
    "viewImport.notesFundSubtype": "各言語テンプレートではローカライズされた選択肢を表示し、取り込み時に内部アクションへ変換します。",
    "viewImport.notesCashAccount": "必須（配当再投資を除く）。買入、定投、解約、現金配当など現金の出入りがあるアクションでは必須です。配当再投資は現金の出入りがないため空白でも構いません。空欄の場合はファンド取り込みルールが検証します。",
    "viewImport.notesFundAccount": "ファンド口座。現在のテンプレートはビュー口座を既定で入力します。",
    "viewImport.notesFundCode": "ファンドコードはファンド記録の識別キーです。ファンド名は任意の表示情報であり、一致判定には使用しません。",
    "viewImport.notesFundAmount": "正の数を入力します。方向はファンド操作によって決まります。",
    "viewImport.notesFundFeeRate": "率で計算する手数料です。1.5 または 1.5% と入力でき、どちらも 1.5% として扱います。",
    "viewImport.notesFundFee": "実際の手数料額を入力します。% のない数値は常に金額として扱います。",
    "viewImport.notesFundNav": "約定基準価額。購入・解約時の口数推定に使い、空欄の場合は 1 として扱います。",
    "viewImport.notesFundUnits": "確認口数。プレビュー検証で保有口数と照合します。",
