    "viewImport.notesFundArrivalDate": "現金入金日。YYYY-MM-DD を推奨します。空欄の場合は確認日を使用します。",
    "viewImport.notesIntroStock": "テンプレートは現在の株式口座を既定にします。株式口座ビュー外から取り込む場合は、株式口座列を入力してください。株式コードが識別キーで、未保有の銘柄情報も取り込み時に作成できます。",
    "viewImport.notesRecognitionStock": "システムはヘッダーで株式取引フィールドを認識します。購入、売却、配当、株式配当、分割、併合、手数料調整、税金調整をシステムの株式操作に変換します。",
    "viewImport.notesStockSettleDate": "受渡日を入力します。YYYY-MM-DD を推奨します。空欄の場合は取引日を使用します。",
    "viewImport.notesStockAccount": "必須です。システムは株式口座を名前、ID、別名、または表示ラベルで識別します。",
    "viewImport.notesStockAction": "各言語テンプレートではローカライズされた選択肢を表示し、取り込み時に内部アクションへ変換します。",
    "viewImport.notesStockMarket": "A 株は上海/深圳/北京のコードを入力するか、証券コードから取引所を推定する CN を入力します。香港株は HK、米国株は US を入力します。",
    "viewImport.notesStockCode": "上場証券取引行では証券コードが必須です。銀行・証券間振替行では空欄にできます。",
    "viewImport.notesStockQuantity": "購入、売却、株式配当、分割、併合など数量系の操作では数量が必要です。現金配当と手数料調整では空欄にできます。",
    "viewImport.notesStockPrice": "価格、約定金額、純額のいずれか 1 つを入力すれば、その他はシステムが算出します。価格を入力した場合、約定金額 = 数量 × 価格です。空欄にすると、取引日の終値で価格を補完します。",
    "viewImport.notesStockAmount": "価格、約定金額、純額のいずれか 1 つを入力すれば、その他はシステムが算出します。購入/売却行では約定金額を直接入力するか、価格や純額だけを入力してシステムに算出させます。配当、手数料調整、銀行・証券間振替など現金行では約定金額または純額が必要です。銀行・証券間振替では、正数は銀行から証券資金口座へ、負数はその逆を表します。",
    "viewImport.notesStockNetAmount": "価格、約定金額、純額のいずれか 1 つを入力すれば、その他はシステムが算出します。純額は実際の入出金額です。純額を入力した場合は価格を空欄にできます。",
    "viewImport.notesStockBankAccount": "銀行・証券間振替行のみ銀行側口座（所有者、機関、口座名）の入力が必要です。通常の証券取引では空欄にできます。",
    "viewImport.notesStockFees": "合計手数料は費用合計で、下のすべての内訳を上書きします。入力した場合はその値を合計として使い、委託手数料や印紙税などの内訳を加算しません。合計手数料が空欄の場合は、内訳手数料を分けて入力でき、自動的に合算されます。すべての手数料欄が空欄の場合は、システムが口座ルールから推定します。",
    "viewImport.notesStockFeeComponent": "合計手数料が空欄の場合の手数料内訳です。すべての手数料欄が空欄の場合、システムが口座ルールから推定します。",
